    // MARK: - After the grocery store

    static let aisleResisting = followUp(
        key: "story.followup.aisleResisting", category: .publicOrder,
        headlines: ["Shoplifting Suspect Pushed Past Security, Then Resisted Deputy", "Woman From Earlier Shoplifting Case Charged With Resisting"],
        law: "resisting", threshold: 5, spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, in discharging a duty of the officer's office, on {DATE}.", ages: 38...66, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped by a store's loss prevention officer at a department store with a scarf in {D.his} bag. When a deputy arrived, {DL} pulled away, dropped to the floor, and refused to stand or give {D.his} name for twelve minutes, then tried to run for the door. The deputy said {DL} was crying and shaking throughout.",
        state: [E(.video, 3, "Store Camera and Body Camera", "{D} refuses to stand, pulls away twice, and starts for the door before the deputy blocks it."),
                E(.document, 2, "Deputy's Report", "Three verbal commands and a request to give a name, none obeyed.")],
        defense: [E(.document, 2, "Therapist's Letter", "{D}'s therapist says stress and shame can freeze a person with the disorder in a standoff.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What did {DL} do?", "\"Sat on the floor, wouldn't stand, wouldn't give a name, and bolted for the door.\""),
               .direct("Did you tell {D.him} to stand?", "\"I told {D.him} to stand three times before I did anything else.\""),
               .direct("What was the call at the store?", "\"A loss prevention officer had stopped {DL} with a scarf in {D.his} bag and asked for a deputy.\""), .direct("What did {DL} do when you arrived?", "\"Sat down on the floor, refused to stand, refused to give a name for twelve minutes, and then bolted for the door.\""), .direct("How many commands did you give?", "\"Three, plus a request to give a name. {DL} did not obey any of them.\""), .direct("What does the camera show?", "\"{DL} refusing to stand, pulling away twice, and starting for the door before I blocked it.\""),
                    .cross("{D.He} was crying.", "\"Yes. {D.He} said 'I did it again.'\""),
               .cross("{D.He} never struck you.", "\"No. {D.He} never struck me, and {D.he} never raised a hand.\""),
                    .cross("{DL} was crying, wasn't {D.he}?", "\"{D.He} was. {D.He} said, 'I did it again,' over and over.\""), .cross("{DL} has a therapist's letter?", "\"The therapist says stress and shame can freeze a person. I did not have that when I gave the commands.\""), .cross("The store did not tell {DL} {D.he} could leave?", "\"That is what {DL} says. I have no record that anyone at the store told {D.him} either way.\"")],
        theory: ("{D} refused three lawful commands and tried to leave while being detained.", "A frightened person with a disorder, in tears, who wasn't a danger to anyone."),
        allocution: "\"I panicked in that store, and my legs wouldn't work, and I was too ashamed to say my name. I've been in this courtroom before, and I'm working on the disorder I have. I'm sorry for the deputy's trouble and for the twelve minutes I made everyone wait.\"",
        truths: ("{DL} had skipped her last two therapy appointments.", "The store had not told {DL} she was free to leave or why she was being held."),
        defendant: [.direct("Why didn't you stand?", "\"My legs wouldn't work. I was so ashamed.\""),
               .direct("Why go for the door?", "\"I wanted to get out. I wasn't thinking.\""),
               .direct("What happened in the store?", "\"I put a scarf in my bag and the officer stopped me. I started shaking and could not think.\""),
               .direct("Why did you sit on the floor?", "\"My legs would not work. I was ashamed and I was crying, and I could not make myself stand.\""),
               .direct("Why did you not give your name?", "\"I could not say anything. I was frozen, and I did not trust myself to say it right.\""),
               .direct("What happened when you were taken outside?", "\"They walked me to the deputy's car. I kept apologizing, and I could not stop shaking until someone brought me water.\""),
                    .cross("Three commands.", "\"I heard them. I heard all three commands, and I understood each one.\""),
               .cross("After your last case.", "\"I know. I'm sorry. I'm standing here again after my last case, and I mean it.\""),
               .cross("You tried to leave while being detained.", "\"I did, and I know that was wrong. I was panicking.\""),
                    .cross("You pulled away from the deputy twice.", "\"I did. I was not trying to hurt anyone. I did not know what to do with my body.\""), .cross("The loss prevention officer never told you that you could leave.", "\"He did not say anything. I assumed I was under arrest, and I panicked.\"")],
        openings: ("A loss prevention officer stopped {D} at a department store with a scarf in {D.his} bag. When a deputy arrived, {D} pulled away, dropped to the floor, refused to stand or give a name for twelve minutes, and then started for the door before the deputy blocked it.", "The defense will say {D} is a frightened person who froze, was crying, and never struck anyone. A therapist's letter says stress and shame can freeze a person, and the store never told {D} {D.he} could leave."),
        closings: ("Three lawful commands, a refusal to give a name for twelve minutes, two pulls away, and a run for the door, all on the store camera and the deputy's body camera. {D} was back after {PRIOR}.", "A crying woman who froze did not strike anyone and said, 'I did it again.' The State must prove {D} resisted on purpose and was not overcome by shame."),
        timeline: [(0, "Afternoon: stopped at the store; the deputy arrives.")],
        identified: "The store camera and the deputy's body camera.",
        impact: nil)

    static let thriftStoreSecond = followUp(
        key: "story.followup.thriftStoreSecond", category: .property,
        headlines: ["Woman Back in Court for Taking Items From Thrift Store", "Second Shoplifting Charge for Defendant in Earlier Case"],
        law: "misdLarceny", threshold: 5, spec: "Stole $62 in clothing and housewares from a retail thrift store, on {DATE}.", ages: 38...66, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was seen on a thrift store camera putting a sweater, a candle, and a ceramic dish into a tote bag over a forty-minute visit, then buying a $2 paperback. {DL} has not missed therapy this time. {D.He} says the relapse came after a stressful week and that {D.he} brought the items back the next morning.",
        state: [E(.video, 3, "Store Camera", "{D} places a sweater, a candle, and a ceramic dish into a tote and pays for a $2 paperback."),
                E(.document, 2, "Manager's Log", "$62 in unpaid items; the same woman had been seen twice in the previous month.")],
        defense: [E(.document, 2, "Return", "{D} returned all three items the next morning with a note: \"I'm sorry.\"")],
        witnessRole: "Store manager",
        exam: [.direct("What did you see?", "\"{DL} putting items into a tote over forty minutes, paying for a book, and leaving.\""),
               .direct("What happened the next day?", "\"{D.He} came back with the items and a note.\""),
               .direct("What did you see on the camera?", "\"{DL} walking the aisles for forty minutes, putting a sweater, a candle and a ceramic dish into a tote bag, then buying a $2 paperback at the register.\""), .direct("What were the items worth?", "\"$62 together. The manager's log shows the same woman had been seen twice in the previous month.\""), .direct("What did {DL} do the next morning?", "\"Came back with all three items and a handwritten note of apology, and asked to speak to me.\""), .direct("How did {DL} act at the register?", "\"{D.He} was crying. {D.He} paid for the book and said nothing about the tote bag, and I could see {D.he} was upset.\""),
                    .cross("{D.He} returned everything.", "\"Yes. {D.He} returned everything that was taken.\""),
               .cross("{D.He} was crying at the register.", "\"{D.He} was. {D.He} was crying at the register, and I could see how upset {D.he} was.\""),
                    .cross("You have no evidence {DL} meant to keep the items, do you?", "\"I know only what the camera shows and what {D.he} did the next morning. {D.He} returned everything, and I cannot say what {D.he} intended in the aisle.\""), .cross("The closet at {DL}'s home held more unreturned items?", "\"That is what the later search turned up. It was not in the store's records, and {DL} says it was from the week {D.his} mother died.\""), .cross("{DL} is a regular customer, isn't {D.he}?", "\"{D.He} shops here, and I have seen {D.him} before. That is how the manager's log noted the earlier visits.\"")],
        theory: ("{D} took items without paying, again.", "A relapse followed by an immediate return and an apology."),
        allocution: "\"I'm trying, and I brought it back. It was the week of my mother's funeral, and I couldn't stop myself, and I felt sick about it afterward. I haven't missed my therapy this time. I'm sorry to the thrift store, and I'll keep working at getting better.\"",
        truths: ("The closet at {DL}'s home held more unreturned items.", "The week of the incident was the week {D.his} mother died."),
        defendant: [.direct("Why did you take them?", "\"I couldn't stop. It was the week of my mother's funeral.\""),
               .direct("Why return them?", "\"I felt sick about it.\""),
               .direct("Why did you take the items?", "\"I could not stop myself. It was the week my mother died, and I felt like I was coming apart.\""),
               .direct("Why did you buy the paperback?", "\"So no one would notice the bag. I know that sounds terrible, and it was a stupid way to think.\""),
               .direct("Why did you bring everything back?", "\"I felt sick about it and could not sleep. I wanted to put it right and tell them I was sorry.\""),
               .direct("Are you getting help?", "\"I am. I had been going to my therapist, and I missed a few appointments that week because of the funeral.\""),
               .cross("You've done this before.", "\"I know. I've done this before, and I'm not going to pretend otherwise.\""),
               .cross("You paid for the book.", "\"So no one would notice.\""),
               .cross("You put the items in the bag over forty minutes.", "\"I did. I walked around in a fog, and I put things in the bag without thinking.\""),
                    .cross("The manager had noticed you in the store twice before.", "\"I know. I was there on other days and took things then too. I did not come back to hide it.\""), .cross("You only returned the items after you were caught on camera.", "\"I returned them the next morning, before anyone called me. I could not stand what I had done.\"")],
        openings: ("{D} was seen on a thrift store camera putting a sweater, a candle and a ceramic dish into a tote bag over forty minutes, then paying for a $2 paperback and leaving. The same woman had been seen twice in the previous month.", "The defense will say it was a relapse during the week of {D}'s mother's death, and that {D} returned every item the next morning with an apology. {D} did not mean to keep anything."),
        closings: ("Forty minutes on camera, three items in a tote, a $2 paperback to cover the bag, and two earlier sightings. {D} was back before this court after {PRIOR}.", "{D} brought everything back the next morning with a note, crying, in the week {D.his} mother died. The State must prove {D} meant to keep the items and not that {D.he} fell apart."),
        timeline: [(0, "Afternoon: items taken."), (1, "{DL} returns them with a note.")],
        identified: "The store camera.",
        impact: nil)

    // MARK: - After the foot chase

    static let footChaseElude = followUp(
        key: "story.followup.footChaseElude", category: .traffic,
        headlines: ["Man From Foot Chase Case Leads Deputies on Car Chase", "Fleeing to Elude Charge Follows Resisting Case"],
        law: "fleeing", threshold: 6, spec: "Operated a motor vehicle on a street while fleeing from a law enforcement officer who was attempting to stop the vehicle, on {DATE}.", ages: 19...40, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was driving at night when a deputy turned on blue lights for a missing headlight. {DL} sped away through two neighborhoods at up to 65 mph, ran a stop sign, and pulled over on {D.his} own after six minutes. {D.He} says {D.he} fled because {D.his} license was suspended and {D.he} was afraid of another arrest.",
        state: [E(.video, 3, "Dash Camera", "{D} accelerates away from the stop, runs a stop sign, and reaches 65 mph in a 35 zone."),
                E(.document, 2, "Dispatch Log", "Six minutes from the blue lights to the stop.")],
        defense: [E(.statement, 1, "Fear", "{D} says {D.he} thought {D.he} would be jailed again for the earlier case.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What happened?", "\"I turned on my lights. {D.He} sped away, ran a stop sign, and hit about 65 in a 35.\""),
               .direct("How did it end?", "\"{D.He} pulled over on a dead-end street and put {D.his} hands out.\""),
               .direct("Why did you turn on your lights?", "\"The SUV had a missing headlight at night on a county road. I stopped it for that reason.\""),
               .direct("What did {DL} do?", "\"Accelerated away through two neighborhoods, ran a stop sign, and reached 65 miles per hour in a 35 zone.\""),
               .direct("What was found afterward?", "\"A bag of marijuana in the car, found later in a search. It was not the reason for the stop.\""),
               .direct("Where did {DL} stop?", "\"On a dead-end street off the second neighborhood. {D.He} turned the engine off and put {D.his} hands out of the window.\""),
                    .cross("Nobody was hurt.", "\"No. It was lucky that nobody was hurt.\""),
               .cross("{D.He} gave up on {D.his} own.", "\"Yes. {D.He} gave up on {D.his} own, without anyone telling {D.him} to.\""),
               .cross("Your lights failed for the first thirty seconds?", "\"The dash camera shows that, yes. I did not know until I reviewed it.\""),
                    .cross("{DL} did not try to fight you?", "\"No. {D.He} was shaking and cooperative once the car stopped. {D.He} said {D.he} was sorry.\""), .cross("You do not know why {DL} ran?", "\"{D.He} told me later that {D.he} was afraid of being jailed. I did not know it when I turned on the lights.\"")],
        theory: ("{D} ran from a deputy in a car, at nearly twice the limit, past a stop sign.", "A scared man who gave himself up in six minutes."),
        allocution: "\"I panicked, and I'm sorry. My license was suspended, and I was scared when those blue lights came on, and I drove away fast through two neighborhoods. I pulled over on my own after six minutes. I know I put people at risk, and I'll accept what the court decides.\"",
        truths: ("{DL} had a bag of marijuana in the car, found later.", "The deputy's lights failed for the first thirty seconds, the dash camera showed."),
        defendant: [.direct("Why did you run?", "\"My license was suspended and I was scared.\""),
               .direct("How fast?", "\"Fast. I don't know exactly how fast, but it was well above the limit.\""),
               .direct("How fast were you going?", "\"Fast, though I do not know exactly. I was above the limit through the neighborhoods, and I know I ran the stop sign.\""),
               .direct("Why did you stop?", "\"I realized I was going to hurt someone. I pulled onto a dead end, put my hands out, and waited.\""),
               .direct("Did you see the deputy's lights come on?", "\"Not right away. I saw them after a few seconds, and I panicked and sped up.\""),
               .direct("What did you do after you were stopped?", "\"I cooperated. I got out when they told me to, and I told them about the marijuana in the car.\""),
                    .cross("You ran a stop sign.", "\"I did. I ran the stop sign, and I'm not going to argue about it.\""),
               .cross("After the foot chase case.", "\"I know. I keep making it worse.\""),
               .cross("You knew you were being stopped.", "\"I did once I saw the lights. I should have pulled over, and I did not.\""),
                    .cross("Sixty-five miles an hour in a thirty-five zone.", "\"I know. I could have killed someone, and I think about that every day.\""), .cross("You had a suspended license.", "\"I did. I should not have been driving at all, and I knew that when I saw the lights.\"")],
        openings: ("After a deputy turned on blue lights for a missing headlight, {D} sped away through two neighborhoods at up to 65 mph in a 35, ran a stop sign, and pulled over after six minutes. The dash camera records the whole pursuit.", "The defense will say {D} was scared, thought {D.he} would be jailed again, and gave {D.himself} up on a dead-end street after six minutes. The deputy's lights failed for the first thirty seconds."),
        closings: ("Nearly twice the limit, a stop sign run, and six minutes through two neighborhoods, with a bag of marijuana in the car. {D} was back after {PRIOR}.", "A frightened man with a suspended license panicked, and when it sank in, stopped and put his hands out. The State must prove {D} meant to flee and not merely to escape a fear."),
        timeline: [(0, "Night: blue lights, six-minute chase.")],
        identified: "The dash camera.",
        impact: nil)

    // MARK: - After the parking lot

    static let managerThreat = followUp(
        key: "story.followup.managerThreat", category: .publicOrder,
        headlines: ["Customer Charged With Threatening Store Manager", "Return Dispute Customer Charged Again"],
        law: "communicatingThreats", threshold: 5, spec: "Willfully threatened to physically injure {V}, a store manager, in a manner a reasonable person would believe would be carried out, on {DATE}.", ages: 28...62, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} called the home goods store three times in one week, asking for the manager, {V}. On the third call, {DL} said, \"I know where you park. I'll be waiting.\" {V} recorded the call and changed {V.his} parking spot.",
        state: [E(.digital, 3, "Call Recording", "{D}: \"I know where you park. I'll be waiting.\""),
                E(.document, 2, "Phone Records", "Three calls from {D}'s number in one week.")],
        defense: [E(.statement, 1, "Venting", "{DL} says it was a figure of speech and {D.he} never went near the store.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What did {V} do after the call?", "\"Changed parking spots and asked for a security escort to the car.\""),
               .direct("Did {DL} come to the store?", "\"Not that we know. We have no record of {D.him} coming into the store.\""),
               .direct("How many calls were there?", "\"Three in one week from {DL}'s number, each asking for {V}, the manager of the home goods store.\""),
               .direct("What was said on the third call?", "\"'I know where you park. I'll be waiting.' {V} recorded the call and gave us the recording.\""),
               .direct("What did {V} do?", "\"Changed parking spots and asked for a security escort to {V.his} car for several days.\""),
               .direct("How did {V} describe the calls?", "\"As escalating. The first two were complaints about a refund, and the third was the first time {V} felt unsafe.\""),
                    .cross("{DL} said it in anger.", "\"With 'I know where you park' in it.\""),
               .cross("{D.He} never showed up.", "\"No. {D.He} never showed up, and no one heard from {D.him} that day.\""),
               .cross("{DL} was at a family event that week?", "\"A witness says so. I have not been able to confirm the dates.\""),
                    .cross("{DL} did not mention a weapon?", "\"No. {D.He} did not mention a weapon or say that {D.he} would hurt anyone.\""), .cross("A truck like {DL}'s was in the lot two days later?", "\"A truck like it was seen at 6 a.m., but I cannot say who was in it. {DL} says {D.he} was not there.\"")],
        theory: ("{D} told the manager {D.he} would be waiting where {V.he} parks.", "Anger on the phone, with nothing behind it."),
        allocution: "\"I lost my temper again, and I called that store three times in a week. I meant that I'd be out in the lot to argue it face to face, not to hurt anyone, but I know how it sounded to {V}. I've been in this room before, and I'll stay away.\"",
        truths: ("{DL}'s truck was seen in the store lot at 6 a.m. two days later.", "{DL} had been at a family event all that week, a witness confirmed."),
        defendant: [.direct("What did you mean?", "\"That I'd be out in the lot to argue it face to face. Not to hurt anyone.\""),
               .direct("Did you go?", "\"No. I didn't go that day.\""),
               .direct("Why did you call the store?", "\"I was upset about a return that was refused. I wanted to speak to the manager and I kept getting transferred.\""),
               .direct("Where were you that week?", "\"At a family event, and a witness can confirm it. I was not near the store.\""),
               .direct("Did you say 'I know where you park'?", "\"Yes. I know the lot because I shop there, and I said it in anger.\""),
               .direct("What was the refund dispute about?", "\"A space heater that stopped working. I had the receipt, and the store said it was past the return window.\""),
                    .cross("'I'll be waiting.'", "\"It was only a way of talking, nothing more.\""),
               .cross("After your last case.", "\"I know. After my last case I promised myself it wouldn't happen again.\""),
               .cross("You called three times in one week.", "\"I did. I kept being transferred, and I got more upset each time.\""),
                    .cross("'I know where you park.'", "\"I said it because I was angry. I know the lot because I shop there.\""), .cross("You called after being told no.", "\"I did. I kept hoping someone would help me, and I took it out on the manager.\"")],
        openings: ("{D} called the home goods store three times in one week asking for the manager, {V}, and on the third call said, 'I know where you park. I'll be waiting.' {V} recorded the call and changed {V.his} parking spot.", "The defense will say {D} was venting over a refused return, meant only that {D.he} would argue it face to face, and never went near the store. A witness places {D} at a family event that week."),
        closings: ("Three calls in a week, a recorded line, 'I know where you park,' and {V} escorted to a car. A truck like {D}'s was seen in the lot two days later, and {D} was back after {PRIOR}.", "An angry call about a refund is not a threat unless meant as one. The State must prove {D} meant {V} to fear harm, and {D} never came near the store."),
        timeline: [(-3, "First call."), (0, "Third call, recorded.")],
        identified: "{V}'s recording.",
        impact: "\"I park three blocks away now and take a different door into the store. I was told over the phone that someone knew where I parked and would be waiting, and I recorded it so someone would believe me. I look over my shoulder every time I leave work.\"")

    // MARK: - After the pond

    static let pondGateChain = followUp(
        key: "story.followup.pondGateChain", category: .property,
        headlines: ["Gate Chain Cut at Farm Pond; Fisherman Charged", "Pond Dispute Escalates to Property Damage"],
        law: "injuryRealProperty", threshold: 5, spec: "Willfully and wantonly damaged real property of {V}, a gate chain and lock, on {DATE}.", ages: 24...64, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, the gate chain at {V}'s farm pond was found cut with bolt cutters, and a trail camera caught a man's truck at the gate. {DL}'s truck matches. {D} says {D.he} was nowhere near the farm and that many local trucks look alike.",
        state: [E(.video, 3, "Trail Camera", "A truck like {D}'s stops at the gate; a man cuts the chain at 5:10 a.m."),
                E(.physical, 2, "Cut Chain", "A hardened chain cut cleanly; replacement cost $140.")],
        defense: [E(.statement, 1, "Alibi", "{DL}'s spouse says {D.he} was asleep at home.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What does the camera show?", "\"A truck like {D}'s, a man with bolt cutters, and the chain falling.\""),
               .direct("Can you see {D.his} face?", "\"No. The truck has a bumper sticker like {DL}'s.\""),
               .direct("What did you find at {V}'s farm pond?", "\"The gate chain cut cleanly with bolt cutters. A hardened chain, which cost $140 to replace.\""),
               .direct("Why do you connect the truck to {DL}?", "\"It has the same bumper sticker as {DL}'s truck, and {V} had told {DL} to stay off the pond.\""),
               .direct("What did you find later?", "\"Bolt cutters with traces of the chain's coating. They were found in a search of {DL}'s truck.\""),
               .direct("What did {V} say about the pond?", "\"That it is stocked, and that {DL} had been warned twice to stay off it. {V} put a chain on the gate after the second warning.\""),
                    .cross("Many trucks look alike.", "\"This one has the same sticker.\""),
               .cross("The plate isn't visible.", "\"No. The plate isn't visible in the video, so I can't read it.\""),
               .cross("The neighbor's son drives a similar truck?", "\"He does, and he later admitted cutting the chain. That is why I do not claim more than I can see.\""),
                    .cross("The camera is grainy?", "\"It is. I cannot see the man's face, only the truck and the tool.\""), .cross("Nobody saw {DL} at the pond that morning?", "\"No one did. The camera is the only record, and it does not show a plate.\"")],
        theory: ("After being told to stay out, {D} cut the chain to fish anyway.", "A look-alike truck on a grainy video."),
        allocution: "\"I shouldn't have gone back to that farm, if it was me, and I'll pay for the chain. I was home that night, and my truck looks like forty others in this county. I know the camera is grainy and I know my history. I'm asking the court to look at what is actually proven.\"",
        truths: ("{DL}'s bolt cutters, found later, had traces of the chain's coating.", "A neighbor's son, who drives a similar truck, admitted cutting the chain."),
        defendant: [.direct("Were you there?", "\"No. I was home all that night.\""),
               .direct("Is that your truck?", "\"It looks like mine. So do forty others.\""),
               .direct("Were you at the farm?", "\"No. I was home all that night, and my spouse was with me.\""),
               .direct("Is that your truck on the camera?", "\"It looks like mine. So do forty others around here, and I cannot say it is not mine.\""),
               .direct("Why do you have bolt cutters?", "\"I use them for work. Everyone around here has a pair, and a trace of coating could have come from anywhere.\""),
               .direct("What do you know about the neighbor's son?", "\"He drives a similar truck, and I heard he cut the chain. I did not talk to him about it.\""),
               .cross("The same bumper sticker.", "\"They sell them at the feed store.\""),
               .cross("After your last case.", "\"After my last case I stayed away from that place.\""),
               .cross("Bolt cutters were in your truck.", "\"Everyone has bolt cutters. I use mine for work, and I never took them to that gate.\""),
                    .cross("You were told to stay off the pond.", "\"I was told, and I stayed off. I did not cut the chain.\""), .cross("The truck on the camera has your sticker.", "\"It has a sticker like mine. A lot of trucks in this county do.\"")],
        openings: ("The gate chain at {V}'s farm pond was found cut with bolt cutters, and a trail camera caught a truck stop at the gate while a man cut the chain at 5:10 a.m. {D}'s truck has the same bumper sticker, and bolt cutters in it carried traces of the chain's coating.", "The defense will say a look-alike truck on a grainy video is not {D}'s, that {D} was asleep at home with {D.his} spouse, and that a neighbor's son who drives a similar truck admitted cutting the chain."),
        closings: ("A truck like {D}'s with the same sticker, bolt cutters with the chain's coating, and an owner who told {D} to stay off the pond after {PRIOR}.", "The bumper sticker is sold at the feed store, forty trucks look alike, and a neighbor's son admitted cutting the chain. The State must prove {D} was the man at the gate."),
        timeline: [(0, "5:10 a.m.: chain cut at the pond gate.")],
        identified: "The trail camera.",
        impact: "\"A new chain and a new lock cost me money every time, and the cattle have gotten into the road more than once. Someone cut the gate with bolt cutters and the trail camera caught the truck. It costs something every time, and I can't watch that gate all day.\"")

    // MARK: - After the revoked license

    static let revokedAgain = followUp(
        key: "story.followup.revokedAgain", category: .traffic,
        headlines: ["Man Stopped Again Driving on Revoked License", "Second Revoked License Charge in Months"],
        law: "dwlr", threshold: 5, spec: "Drove a motor vehicle on a public highway while {D.his} driver's license was revoked, on {DATE}.", ages: 25...60, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was stopped again, this time at a checkpoint near the poultry plant at 5:15 a.m. {DL}'s license was still revoked. {D.He} said {D.he} had a new address on file and a payment plan for the fines, and still had no way to reach work.",
        state: [E(.document, 3, "DMV Records", "License revoked; address updated after the earlier case; a payment plan not yet started."),
                E(.video, 2, "Checkpoint Camera", "{D} presents an expired ID and says, \"I know.\"")],
        defense: [E(.document, 2, "Payment Plan", "A signed payment plan for the fines, with the first installment due next week.")],
        witnessRole: "State Highway Patrol trooper",
        exam: [.direct("What did you find?", "\"A revoked license. {D.He} said 'I know.'\""),
               .direct("Was the notice mailed?", "\"To the updated address this time.\""),
               .direct("Where was the checkpoint?", "\"Near the poultry plant at 5:15 a.m. We stop vehicles one at a time and check license and registration.\""),
               .direct("What did {DL} present?", "\"An expired ID, and said, 'I know,' when I told {D.him} the license was revoked.\""),
               .direct("What do the DMV records show?", "\"The license is revoked, the address was updated after the earlier case, and a payment plan for the fines has not yet started.\""),
               .direct("Had you seen {DL} driving before?", "\"A coworker said {DL} had driven to the plant daily for two weeks. I had not seen {D.him} personally.\""),
               .cross("{D.He} has a payment plan.", "\"It hasn't started. {D.He} has a payment plan, but the first payment isn't due yet.\""),
               .cross("{D.He} was going to work.", "\"That's what {D.he} said. {D.He} told me {D.he} was on {D.his} way to work.\""),
               .cross("{DL}'s ride had quit the week before?", "\"A coworker confirmed that. It does not make the license valid.\""),
                    .cross("{DL} was honest with you at the checkpoint?", "\"{D.He} said 'I know' as soon as I asked about the license. {D.He} did not try to hide anything.\""), .cross("The earlier notices had gone to an old address?", "\"They had. The record shows {DL} updated the address after the earlier case, and the new notice went there.\"")],
        theory: ("{D} knew {D.his} license was revoked and drove anyway.", "A worker with no other way to a job and a plan to fix it."),
        allocution: "\"I'm making the payments on my fines, and I need this job. My ride quit on me, and I'd lose my place at the plant if I couldn't get there at five in the morning. I knew my license was revoked, and I'm sorry I drove anyway. I've updated my address and I'm working on getting it back.\"",
        truths: ("{DL} had been seen driving to the plant daily for two weeks.", "{DL}'s ride had quit a week earlier, a coworker confirmed."),
        defendant: [.direct("Why drive?", "\"My ride quit and I'd lose the job.\""),
               .direct("Did you know?", "\"Yes. I knew, and I should have said something sooner.\""),
               .direct("Why were you driving?", "\"My ride quit the week before, and I would have lost my job at the plant. I had no one else to take me.\""),
               .direct("Did you know your license was revoked?", "\"Yes. I knew, and I should have said something sooner. I told the trooper I knew.\""),
               .direct("What is the payment plan?", "\"I signed it to pay my fines and get my license back. The first payment is due next week.\""),
               .direct("Where were you headed?", "\"To work at the plant. I start at six, and I was early.\""),
               .cross("After your last case.", "\"I know. I was trying to fix it.\""),
               .cross("The payment plan hasn't started.", "\"It starts next week. The first payment is due then.\""),
               .cross("You knew you could not drive.", "\"I did, and I did it because I did not have another way.\""),
                    .cross("You drove to the plant for two weeks.", "\"I did, because I needed the job. I never claimed I had a right to.\""), .cross("You knew the license was revoked the whole time.", "\"I did. I was trying to get it back, and I had no other way to work.\"")],
        openings: ("{D}, whose license was still revoked, was stopped at a checkpoint near the poultry plant at 5:15 a.m. {D} handed over an expired ID and said, 'I know.' A coworker says {D} drove to the plant daily for two weeks.", "The defense will say {D}'s ride quit and {D} would have lost {D.his} job, that {D} has a signed payment plan to get the license back, and that {D} was honest with the trooper."),
        closings: ("The license was revoked, the notice went to the updated address, and {D} admitted, 'I know.' {D} had driven to the plant daily for two weeks, after {PRIOR}.", "A worker with no ride and a payment plan about to begin told the trooper the truth. The State must prove {D} drove knowing the license was revoked and not out of need."),
        timeline: [(0, "5:15 a.m.: checkpoint near the plant.")],
        identified: "A checkpoint stop.",
        impact: nil)

    // MARK: - After the glove box

    static let paraphernaliaPipe = followUp(
        key: "story.followup.paraphernaliaPipe", category: .drugs,
        headlines: ["Glass Pipe Found at Traffic Stop Weeks After Marijuana Case", "Paraphernalia Charge for Defendant in Earlier Drug Case"],
        law: "possParaphernalia", threshold: 5, spec: "Knowingly possessed drug paraphernalia, a glass pipe with residue, on {DATE}.", ages: 19...45, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy stopped {D} for an expired tag and found a glass pipe with burnt residue in the cup holder. {DL} said it belonged to a passenger. {D.He} was alone in the car.",
        state: [E(.physical, 3, "The Pipe", "A glass pipe with burnt residue in the cup holder.", .search),
                E(.statement, 2, "Statement", "{D} told the deputy, \"It's not mine, a friend left it.\"")],
        defense: [E(.statement, 1, "Borrowed Car", "{DL} says the car was borrowed that morning.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("Where was the pipe?", "\"In the cup holder, in plain view.\""),
               .direct("Who else was in the car?", "\"Nobody. {D.He} was alone in the car.\""),
               .direct("Why did you stop {DL}?", "\"For an expired tag. The stop was routine, and {D.he} pulled over promptly.\""),
               .direct("What did you see in the car?", "\"A glass pipe with burnt residue in the cup holder, in plain view from the driver's window.\""),
               .direct("What did {DL} say?", "\"'It's not mine, a friend left it.' {D.He} said the car was borrowed that morning.\""),
               .direct("What was found on the pipe?", "\"A thumbprint matching {DL}'s. The residue was not tested for THC.\""),
               .cross("The car was borrowed.", "\"{D.He} said so after I found it.\""),
               .cross("Residue wasn't tested for THC.", "\"It didn't need to be.\""),
               .cross("The owner of the car later said the pipe was his?", "\"He did, after the arrest. I did not know that when I found it.\""),
                    .cross("You did not see {DL} touch the pipe.", "\"No. I saw it in the cup holder, and the thumbprint came back from the lab afterward.\""), .cross("The stop was for an expired tag, not drugs.", "\"Correct. The tag was the only reason I pulled {D.him} over, and I did not search the car until I saw the pipe.\"")],
        theory: ("{D} was alone in a car with a used pipe in plain view.", "A borrowed car and a friend's pipe."),
        allocution: "\"I'm trying to stay out of trouble. That pipe wasn't mine. I'd borrowed the car, and I didn't know it was in the cup holder. I've been in this courtroom before, and I know it makes my word harder to believe. I'm asking the court to give me the benefit of the doubt this once.\"",
        truths: ("{DL}'s thumb print was on the pipe.", "The owner of the car later admitted the pipe was his."),
        defendant: [.direct("Whose pipe?", "\"Not mine. I borrowed the car.\""),
               .direct("Did you see it?", "\"No. I didn't see it, and nobody pointed it out.\""),
               .direct("Whose car were you driving?", "\"A friend's. I borrowed it that morning because mine was not running.\""),
               .direct("Did you know the pipe was there?", "\"I did not. I did not notice it, and nobody pointed it out to me.\""),
               .direct("How did your thumbprint get on it?", "\"I may have moved it when I put my drink in the cup holder. I did not know what it was.\""),
               .direct("What did you tell the deputy?", "\"That it was not mine. I told him the car was borrowed, and that is what I believed.\""),
               .cross("It was in plain view.", "\"I wasn't looking. It was in plain view, but I wasn't paying attention.\""),
               .cross("After your last case.", "\"I know. After my last case I promised myself it wouldn't happen again.\""),
               .cross("Your thumbprint was on it.", "\"I may have touched it. I do not know how, and I did not know it was a pipe.\""),
                    .cross("You told the deputy a friend left it, but you said the car was borrowed.", "\"Both are true. The friend lent me the car, and I think he left the pipe in it.\""), .cross("You were alone in the car the whole time.", "\"I was. I drove it from my friend's house straight to where the deputy stopped me.\"")],
        openings: ("A deputy stopped {D} for an expired tag and found a glass pipe with burnt residue in the cup holder, in plain view. {D} was alone in the car and said, 'It's not mine, a friend left it.'", "The defense will say {D} borrowed the car that morning, never noticed the pipe, and that the car's owner later admitted the pipe was his. {D} did not know it was there."),
        closings: ("A pipe in plain view in the cup holder, a thumbprint on it, and a driver alone in the car, {D}, back after {PRIOR}. The deputy found it within a minute of looking.", "A borrowed car holds what its owner left, and the owner later admitted the pipe was his. The State must prove {D} knew it was in the car and meant to possess it."),
        timeline: [(0, "Afternoon: stop for an expired tag.")],
        identified: "A traffic stop.",
        impact: nil,
        doctrines: ["searchSeizure", "burdenOfProof"])

