    static let keyedCar = followUp(
        key: "story.followup.keyedCar", category: .property,
        headlines: ["Car Keyed in Church Parking Lot Weeks After Assault Case", "Damaged Vehicle Brings Second Charge for Church Lot Dispute"],
        law: "injuryPersonalProperty", threshold: 5, spec: "Willfully and wantonly injured personal property of {V}, a car, causing damage of $1,100, on {DATE}.", ages: 28...68, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s car was found keyed along both doors and the hood in the church parking lot during a Sunday service. A church camera caught a man in a gray jacket near the car, and {V} says {D} was the only person who had a grudge. {DL} says {D.he} was inside the sanctuary the entire service.",
        state: [E(.video, 2, "Church Camera", "A man in a gray jacket walks along the driver's side; his face isn't visible."),
                E(.document, 2, "Repair Estimate", "$1,100 to repaint both doors and the hood.")],
        defense: [E(.statement, 1, "Alibi", "The pastor says {D} was in the sanctuary for the whole service.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What does the camera show?", "\"A gray jacket walking along the side of the car. No face.\""),
               .direct("Why {DL}?", "\"The earlier case. Nobody else had a reason.\""),
               .direct("Where was the car when it was keyed?", "\"In the church parking lot, during a Sunday service. {V} found it keyed along both doors and the hood when {V.he} came out.\""),
               .direct("What did the repair estimate say?", "\"$1,100 to repaint both doors and the hood.\""),
               .direct("Why did {V} suspect {DL}?", "\"{V} says {D} was the only person who had a grudge, after the earlier case. {D.He} was at the church that morning.\""),
               .direct("What did you find on {DL}'s jacket?", "\"A gray jacket with paint transfer consistent with the car. It was in {D.his} car when we asked.\""),
               .cross("{DL} was in the service.", "\"The pastor says so. {DL} was in the service, according to the pastor.\""),
               .cross("Gray jackets are common.", "\"Yes. Gray jackets are common, and I can't say it was this one.\""),
               .cross("The man on the video was {V}'s nephew?", "\"That came out later, along with the fact that he owed {V} money. It does not clear {D.him} of the jacket.\""),
                    .cross("The pastor said {DL} was in the sanctuary?", "\"He said so, and the church camera shows {D.him} going in and coming out. The camera cannot see inside the sanctuary.\""), .cross("{V} had no direct evidence it was {DL}?", "\"{V} had a grudge theory and a camera. The paint on the jacket is what ties {D.him} to the car.\"")],
        theory: ("{D} keyed {V}'s car in revenge after the court case.", "A gray jacket and a grudge, with a pastor to say {D.he} was inside."),
        allocution: "\"I'd never do something like that, and I'm sorry for the trouble. I was inside the sanctuary the entire service, and the pastor can tell you. I let that old disagreement with {V} go a long time ago. I'm sorry that {V.his} car was damaged, and I hope you find the person.\"",
        truths: ("{DL}'s gray jacket had paint transfer consistent with the car.", "The man in the video was {V}'s own nephew, who owed {V} money."),
        defendant: [.direct("Were you in the service?", "\"The whole thing. I was at the service from beginning to end.\""),
               .direct("Did you hold a grudge?", "\"I held a grudge for a while, but I let it go.\""),
               .direct("Where were you during the service?", "\"Inside the sanctuary the whole time. The pastor can tell you I was there from the first hymn to the last.\""),
               .direct("Do you own a gray jacket?", "\"I do. So does half the congregation, and I wore it that morning because it was cold.\""),
               .direct("What is your history with {V}?", "\"We had a disagreement over a parking space. I held a grudge for a while, but I let it go.\""),
               .direct("Did you go out to the lot?", "\"Not during the service. I went out afterward with everyone else, and I never went near {V}'s car.\""),
               .cross("A gray jacket.", "\"I own one. So does everyone.\""),
               .cross("You left for ten minutes.", "\"No. I was in my seat for the entire service, and I never left the sanctuary.\""),
               .cross("The paint on your jacket.", "\"I do not know where it came from. I paint at home, and I had the jacket in the garage.\""),
               .cross("{V} says you were the only person with a grudge.", "\"{V} is wrong about that. Plenty of people disagreed with {V.him}, and I let mine go.\""),
                    .cross("The church camera also shows your truck leaving the lot early?", "\"It shows me leaving after the service ended. Everyone left around the same time, and my truck was in line with the rest.\"")],
        openings: ("{V}'s car was found keyed along both doors and the hood in the church parking lot during a Sunday service. A church camera caught a man in a gray jacket near the car, and {V} says {D} was the only person who had a grudge.", "The defense will say {D} was inside the sanctuary the entire service, as the pastor will confirm, and that gray jackets are common. The man on the camera was {V}'s own nephew, who owed {V} money."),
        closings: ("A gray jacket on the camera, a gray jacket with paint transfer in {D}'s car, and a grudge left over from {PRIOR}. Only one person had a reason to key {V}'s car.", "The pastor says {D} was in the sanctuary, the face on the camera is hidden, and the man was {V}'s nephew. The State must prove {D} left the service and keyed the car."),
        timeline: [(0, "Sunday morning: {V}'s car keyed during the service.")],
        identified: "The church camera.",
        impact: "\"I checked my car after every service for months after that Sunday. Someone keyed both doors and the hood in the church parking lot while I was inside praying. The body shop quoted me nine hundred dollars, and I'm still paying it off.\"")

