    static let pawnedDrill = followUp(
        key: "story.followup.pawnedDrill", category: .property,
        headlines: ["Stolen Power Tools Found at Pawn Shop; Defendant Charged Again", "Pawn Ticket Ties Man to Stolen Saw"],
        law: "possStolen", threshold: 5, spec: "Possessed a circular saw valued at $320 belonging to {V}, knowing and having reasonable grounds to believe it stolen, on {DATE}.", ages: 19...44, victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}'s circular saw, taken from an unlocked truck, turned up at a pawn shop on a ticket signed by {D}. {DL} says {D.he} found the saw at a job site and sold it for a few dollars.",
        state: [E(.document, 3, "Pawn Ticket", "A ticket signed by {D} four days after the theft; the serial number matches {V}'s tool."),
                E(.document, 2, "Value", "A $320 circular saw, two years old.")],
        defense: [E(.statement, 1, "Found Saw", "{D} says a coworker left it at the job site.")],
        witnessRole: "Pawn shop clerk",
        exam: [.direct("Who pawned the saw?", "\"{DL}. Signed the ticket with {D.his} ID.\""),
               .direct("What did {D.he} say about it?", "\"That it was {D.his} brother's.\""),
               .direct("What did {DL} bring in?", "\"A circular saw, a $320 tool that is two years old, and asked for a few dollars for it.\""),
               .direct("What did {DL} sign?", "\"A pawn ticket with {D.his} own ID, four days after the saw was stolen from {V}'s unlocked truck.\""),
               .direct("What did the serial number show?", "\"It matched {V}'s purchase record. The pawn shop reported it to the sheriff's database, which flagged it.\""),
               .direct("What was found at {DL}'s home?", "\"The saw's case, with {V}'s initials on it. {D.He} had not pawned the case.\""),
               .cross("{D.He} used {D.his} real ID.", "\"Yes. {D.He} used {D.his} real ID, so there was nothing hidden.\""),
               .cross("You see a lot of used tools.", "\"All day. I see a lot of used tools come through the store every day.\""),
               .cross("A coworker confirmed leaving the saw?", "\"He did, later. He left it at the job site and never claimed it.\""),
                    .cross("A pawn ticket by itself does not prove {DL} took the saw?", "\"No. It proves {D.he} pawned it. The truck was unlocked, and I do not know who took the saw from it.\""), .cross("The saw was worth only a few dollars to {DL}?", "\"{D.He} asked for twenty. The saw is worth $320, and I paid ten for it, since it was pawned.\"")],
        theory: ("{D} pawned a saw {D.he} knew didn't belong to {D.him}.", "A found saw and an honest ID."),
        allocution: "\"I'm trying to stay straight. I found that saw sitting at a job site, and I thought it was abandoned, and I needed twenty dollars. I put my own name on the ticket because I wasn't hiding. I'm sorry to {V}, and I'll return the money or the saw.\"",
        truths: ("The saw's case, found at {DL}'s home, had {V}'s initials on it.", "A coworker confirmed leaving the saw at the job site and never claiming it."),
        defendant: [.direct("Where did you get the saw?", "\"At a job site. It was just sitting there.\""),
               .direct("Why pawn it?", "\"I needed twenty dollars. I pawned it because I needed the cash that day.\""),
               .direct("Why did you pawn it?", "\"I needed twenty dollars that day. I did not think anyone would miss it.\""),
               .direct("Why did you tell the clerk it was your brother's?", "\"I panicked and said the first thing that came into my head. I got scared when he asked.\""),
               .direct("Whose saw was it?", "\"I thought a coworker left it. He told the deputy he left it at the job site and never claimed it.\""),
               .direct("Did the clerk ask you any questions about the saw?", "\"He asked whether it was mine, and I said it was my brother's. I did not think he would care, and I wish I had told the truth.\""),
                    .cross("You told the clerk it was your brother's.", "\"I panicked. I told the clerk it was my brother's because I got scared.\""),
               .cross("After your last case.", "\"I know. After my last case I promised myself it wouldn't happen again.\""),
               .cross("The case had {V}'s initials on it.", "\"I never looked at the case. I did not know whose initials were on it.\""),
                    .cross("You pawned a $320 saw for twenty dollars.", "\"I did, because I needed cash fast. I did not think about what it was worth.\""), .cross("The saw case with {V}'s initials was at your house.", "\"I did not look at it. I took the case home and put it in the garage.\"")],
        openings: ("{V}'s circular saw was taken from an unlocked truck and turned up four days later at a pawn shop on a ticket signed by {D}. The serial number matches {V}'s record, and the saw's case with {V}'s initials was at {D}'s home.", "The defense will say {D} found the saw at a job site where a coworker left it and sold it for a few dollars under {D.his} own ID. A coworker confirms leaving the saw."),
        closings: ("The ticket carries {D}'s signature, the serial number matches, the case with {V}'s initials was at {D}'s home, and {D} told the clerk it was {D.his} brother's. {D} was back after {PRIOR}.", "A man who signs {D.his} own name on a pawn ticket is not hiding. A coworker left the saw at the job site, and the State must prove {D} knew it was stolen."),
        timeline: [(0, "{DL} pawns the saw.")],
        identified: "The pawn ticket.",
        impact: "\"That was the saw I use every day on the job, and it was taken from an unlocked truck. Another set of my tools gone, and I lost two days of work waiting for a replacement. I carry everything inside every night now, and it's exhausting.\"")

