    static let scriptRefill = followUp(
        key: "story.followup.scriptRefill", category: .drugs,
        headlines: ["Student Charged With Forging Prescription for Pills", "Prescription Fraud Charge Follows Adderall Case"],
        law: "prescriptionFraud", threshold: 6, spec: "Obtained a controlled substance by forging a prescription, a forged prescription for amphetamine salts, on {DATE}.", ages: 19...30, victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a pharmacist refused to fill a prescription for 60 Adderall presented by {D}, noticing the doctor's signature didn't match and the clinic's phone number was a cell phone. {DL} said {D.he} got the prescription from a friend.",
        state: [E(.document, 3, "The Prescription", "A prescription on a clinic form with a signature that doesn't match the doctor's; the clinic number is a cell phone."),
                E(.statement, 2, "Pharmacist's Call", "The clinic confirmed it never issued the prescription.")],
        defense: [E(.statement, 1, "Friend's Script", "{D} says a friend gave {D.him} the paper and said it was real.")],
        witnessRole: "Pharmacist",
        exam: [.direct("Why did you refuse to fill it?", "\"The signature was off and the number was a cell phone.\""),
               .direct("What did you do?", "\"I called the clinic. They'd never seen it.\""),
               .direct("What did {DL} present?", "\"A prescription for 60 Adderall on a clinic form. The doctor's signature did not match the one I have on file.\""),
               .direct("What else was wrong with it?", "\"The clinic's phone number on the form was a cell phone, not a business line.\""),
               .direct("What did the clinic say?", "\"I called the number in the directory. They had never issued the prescription.\""),
               .direct("What did {DL} do?", "\"Waited while I made the call, then left when I said I was calling the clinic. {D.He} did not argue.\""),
               .cross("{D.He} didn't try to run.", "\"{D.He} waited while I called, then left.\""),
               .cross("{D.He} may not have known it was forged.", "\"That's possible. {D.He} may not have known it was forged.\""),
               .cross("A friend later admitted forging it?", "\"I have learned that. I did not know it at the counter.\""),
                    .cross("A phone number on a form can be copied from anywhere, can't it?", "\"It can. The cell phone number was what raised my suspicion, and then the clinic confirmed the form was not theirs.\""), .cross("{DL} did not try to take the prescription back?", "\"{D.He} left it on the counter. I kept it and gave it to the deputies.\"")],
        theory: ("After the earlier case, {D} presented a forged prescription for the same drug.", "A friend handed {D} a fake without {D.his} knowing."),
        allocution: "\"I made a bad choice, and I'm sorry. A friend handed me that prescription and told me it was real, and I should have known better. I've been in this courtroom before, and I know I'm responsible for what I carry into a pharmacy. I'll stay away from that friend.\"",
        truths: ("{DL}'s phone held a photo of the forged form.", "The friend later admitted forging the prescription and giving it to {D}."),
        defendant: [.direct("Where did you get it?", "\"A friend. {D.He} said it was real.\""),
               .direct("Did you know?", "\"No.\"", "\"I had a feeling.\""),
               .direct("Where did you get the prescription?", "\"A friend gave it to me. {D.He} said it was real, and that {D.he} had been given an extra.\""),
               .direct("Did you know it was forged?", "\"No. It looked like any other prescription, and I do not know what a real one looks like.\""),
